import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  Img,
  staticFile,
} from "remotion";
import React from "react";

export const fps = 25;
export const durationInFrames = 275;

const tc = (seconds: number) => Math.round(seconds * 25);

const IG_ORANGE = "#F77737";
const IG_PINK = "#E1306C";
const IG_PURPLE = "#833AB4";
const IG_DARK_TEXT = "#1A0A2E";

const BADGE_HEIGHT = 120;

const FadeIn: React.FC<{ delay: number; children: React.ReactNode; direction?: "up" | "down" }> = ({ delay, children, direction = "up" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: { damping: 170, stiffness: 80 } });
  const yShift = direction === "up" ? 60 : -60;
  return (
    <div style={{ opacity: p, transform: `translateY(${interpolate(p, [0, 1], [yShift, 0])}px)` }}>
      {children}
    </div>
  );
};

const SpringIn: React.FC<{ delay: number; children: React.ReactNode; direction?: "up" | "left" | "right" | "scale" }> = ({ delay, children, direction = "up" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: { damping: 180, stiffness: 80 } });
  let transform = "";
  if (direction === "up") transform = `translateY(${interpolate(p, [0, 1], [80, 0])}px)`;
  if (direction === "left") transform = `translateX(${interpolate(p, [0, 1], [-120, 0])}px)`;
  if (direction === "right") transform = `translateX(${interpolate(p, [0, 1], [120, 0])}px)`;
  if (direction === "scale") transform = `scale(${interpolate(p, [0, 1], [0.7, 1])})`;
  return (
    <div style={{ opacity: p, transform }}>
      {children}
    </div>
  );
};

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Screep White Pink.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// Bulk Download card — appears FIRST (at scene start, i.e. frame 0 of MainScene = tc(1) globally)
const BulkDownloadCard: React.FC<{ globalFrame: number }> = ({ globalFrame }) => {
  const { fps } = useVideoConfig();

  // Appears immediately at start of MainScene
  const cardEntrance = spring({ frame: globalFrame, fps, delay: 5, config: { damping: 180, stiffness: 80 } });

  const downloadProgress = spring({
    frame: globalFrame,
    fps,
    delay: 20,
    config: { damping: 170, stiffness: 60 },
  });

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
      <div style={{
        opacity: cardEntrance,
        transform: `translateX(${interpolate(cardEntrance, [0, 1], [-120, 0])}px)`,
        backgroundColor: "rgba(255,255,255,0.80)",
        borderRadius: 32,
        padding: "72px 80px",
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        boxShadow: "0 8px 64px rgba(247,119,55,0.10)",
        backdropFilter: "blur(12px)",
        height: 900,
      }}>
        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 24, marginBottom: 60 }}>
          <span style={{ fontSize: 60 }}>⬇️</span>
          <div>
            <div style={{ fontSize: 56, fontWeight: 800, color: IG_DARK_TEXT, lineHeight: 1.1 }}>
              Bulk Download
            </div>
            <div style={{ fontSize: 38, fontWeight: 500, color: "#6D7178", marginTop: 8 }}>
              Can't export anything at scale
            </div>
          </div>
        </div>

        {/* File list */}
        <div style={{ display: "flex", flexDirection: "column", gap: 40, flex: 1, justifyContent: "center" }}>
          {[
            { name: "competitor_ad_jan.mp4", size: "12.4 MB" },
            { name: "competitor_ad_feb.mp4", size: "8.7 MB" },
            { name: "competitor_ad_mar.mp4", size: "15.2 MB" },
          ].map((file, i) => {
            const fileProgress = spring({
              frame: globalFrame,
              fps,
              delay: 18 + i * 16,
              config: { damping: 170, stiffness: 80 },
            });
            return (
              <div key={file.name} style={{
                opacity: fileProgress,
                transform: `translateX(${interpolate(fileProgress, [0, 1], [60, 0])}px)`,
                display: "flex",
                alignItems: "center",
                gap: 28,
                backgroundColor: "rgba(247,119,55,0.07)",
                borderRadius: 16,
                padding: "32px 40px",
              }}>
                <span style={{ fontSize: 44 }}>🎬</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 36, fontWeight: 600, color: IG_DARK_TEXT }}>{file.name}</div>
                  <div style={{ fontSize: 30, fontWeight: 500, color: "#848890", marginTop: 6 }}>{file.size}</div>
                </div>
                <div style={{ width: 200, display: "flex", flexDirection: "column", gap: 10, alignItems: "flex-end" }}>
                  <div style={{
                    width: 200,
                    height: 12,
                    borderRadius: 6,
                    backgroundColor: "rgba(247,119,55,0.12)",
                    overflow: "hidden",
                  }}>
                    <div style={{
                      height: "100%",
                      width: interpolate(downloadProgress, [0, 1], [0, 200]),
                      borderRadius: 6,
                      background: `linear-gradient(90deg, ${IG_ORANGE}, ${IG_PINK})`,
                    }} />
                  </div>
                  <div style={{ fontSize: 28, fontWeight: 700, color: IG_ORANGE }}>
                    {Math.round(interpolate(downloadProgress, [0, 1], [0, 100]))}%
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

// Creative Strategy card — appears at tc(3.76) of the global timeline
// globalFrame is already the raw frame; we pass the local frame offset for animations
const CreativeStrategyCard: React.FC<{ globalFrame: number }> = ({ globalFrame }) => {
  const { fps } = useVideoConfig();

  // Creative strategy starts appearing at 3.76s globally (i.e. 3.76s after scene start)
  const appearFrame = tc(3.76);
  const localFrame = Math.max(0, globalFrame - appearFrame);

  const cardEntrance = spring({ frame: localFrame, fps, delay: 0, config: { damping: 180, stiffness: 80 } });

  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun"];
  const competitorData = [12, 18, 14, 28, 35, 42];
  const maxVal = 50;

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
      <div style={{
        opacity: cardEntrance,
        transform: `translateX(${interpolate(cardEntrance, [0, 1], [120, 0])}px)`,
        backgroundColor: "rgba(255,255,255,0.80)",
        borderRadius: 32,
        padding: "72px 80px",
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        boxShadow: "0 8px 64px rgba(131,58,180,0.10)",
        backdropFilter: "blur(12px)",
        height: 900,
      }}>
        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 24, marginBottom: 60 }}>
          <span style={{ fontSize: 60 }}>📈</span>
          <div>
            <div style={{ fontSize: 56, fontWeight: 800, color: IG_DARK_TEXT, lineHeight: 1.1 }}>
              Creative Strategy
            </div>
            <div style={{ fontSize: 38, fontWeight: 500, color: "#6D7178", marginTop: 8 }}>
              Can't track evolution over time
            </div>
          </div>
        </div>

        {/* Bar chart */}
        <div style={{ display: "flex", flexDirection: "column", gap: 52, flex: 1, justifyContent: "center" }}>
          {months.map((month, i) => {
            const barProgress = spring({
              frame: localFrame,
              fps,
              delay: 12 + i * 12,
              config: { damping: 170, stiffness: 80 },
            });
            const barWidth = interpolate(barProgress, [0, 1], [0, (competitorData[i] / maxVal) * 900]);

            return (
              <div key={month} style={{
                display: "flex",
                alignItems: "center",
                gap: 32,
              }}>
                <div style={{ fontSize: 36, fontWeight: 700, color: "#848890", width: 80, textAlign: "right", flexShrink: 0 }}>
                  {month}
                </div>
                <div style={{
                  flex: 1,
                  height: 44,
                  borderRadius: 12,
                  backgroundColor: "rgba(131,58,180,0.08)",
                  overflow: "hidden",
                }}>
                  <div style={{
                    height: "100%",
                    width: barWidth,
                    borderRadius: 12,
                    background: `linear-gradient(90deg, ${IG_PURPLE}, ${IG_PINK})`,
                    opacity: 0.85,
                  }} />
                </div>
                <div style={{ fontSize: 40, fontWeight: 800, color: IG_PINK, width: 80, flexShrink: 0 }}>
                  {competitorData[i]}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const MainScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Left badge (Export not available) — appears right at the start
  const leftBadgeP = spring({ frame, fps, delay: 60, config: { damping: 170, stiffness: 80 } });

  // Right badge (Not visible in static library) — appears at tc(3.76)
  const rightAppearFrame = tc(3.76);
  const rightLocalFrame = Math.max(0, frame - rightAppearFrame);
  const rightBadgeP = spring({ frame: rightLocalFrame, fps, delay: 18, config: { damping: 170, stiffness: 80 } });

  return (
    <AbsoluteFill
      style={{
        fontFamily: "sans-serif",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Background image */}
      <Img
        src={staticFile("assets/backgrounds/Screep White Pink.png")}
        style={{ position: "absolute", width: "100%", height: "100%", objectFit: "cover" }}
      />

      {/* Subtle overlay */}
      <div style={{
        position: "absolute",
        inset: 0,
        background: "rgba(255,255,255,0.18)",
        pointerEvents: "none",
      }} />

      <div style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 0,
        width: 3200,
        position: "relative",
      }}>
        {/* Cards row — Bulk Download on LEFT, Creative Strategy on RIGHT */}
        <div style={{
          display: "flex",
          gap: 72,
          width: "100%",
          alignItems: "stretch",
          justifyContent: "center",
        }}>
          {/* LEFT: Bulk Download (appears first) */}
          <BulkDownloadCard globalFrame={frame} />

          {/* RIGHT: Creative Strategy (appears at 3.76s) */}
          <CreativeStrategyCard globalFrame={frame} />
        </div>

        {/* Badges row — OUTSIDE cards, perfectly aligned side by side */}
        <div style={{
          display: "flex",
          gap: 72,
          width: "100%",
          marginTop: 40,
        }}>
          {/* Left badge: Export not available (matches Bulk Download card) */}
          <div style={{ flex: 1 }}>
            <div style={{
              opacity: leftBadgeP,
              transform: `translateY(${interpolate(leftBadgeP, [0, 1], [30, 0])}px)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 20,
              backgroundColor: "rgba(247,119,55,0.08)",
              borderRadius: 16,
              height: BADGE_HEIGHT,
              boxSizing: "border-box",
            }}>
              <span style={{ fontSize: 36 }}>🚫</span>
              <div style={{ fontSize: 36, fontWeight: 700, color: IG_ORANGE }}>
                Export not available
              </div>
            </div>
          </div>

          {/* Right badge: Not visible in static library (matches Creative Strategy card) */}
          <div style={{ flex: 1 }}>
            <div style={{
              opacity: rightBadgeP,
              transform: `translateY(${interpolate(rightBadgeP, [0, 1], [30, 0])}px)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 20,
              backgroundColor: "rgba(225,48,108,0.08)",
              borderRadius: 16,
              height: BADGE_HEIGHT,
              boxSizing: "border-box",
            }}>
              <span style={{ fontSize: 36 }}>🚫</span>
              <div style={{ fontSize: 36, fontWeight: 700, color: IG_PINK }}>
                Not visible in static library
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default function MyVideo() {
  const introFrames = tc(1);
  const contentFrames = durationInFrames - introFrames;

  return (
    <AbsoluteFill style={{ fontFamily: "sans-serif" }}>
      {/* 1 second background only */}
      <Sequence from={0} durationInFrames={introFrames}>
        <Background />
      </Sequence>

      {/* Main scene — starts at 1s */}
      <Sequence from={introFrames} durationInFrames={contentFrames}>
        <MainScene />
      </Sequence>
    </AbsoluteFill>
  );
}
